type SpecId = "frost" | "arcane" | "fire";
export default function Mage() {
  const [rawSpec, setSpec] = useCanvasState<string>("mage-spec", "fire");
  const spec: SpecId = rawSpec === "frost" || rawSpec === "arcane" ? rawSpec : "fire";
  const specPills = (
    <Row gap={8} wrap>
      <Pill active={spec === "fire"} onClick={() => setSpec("fire")}>Fire</Pill>
      <Pill active={spec === "arcane"} onClick={() => setSpec("arcane")}>Arcane (частичный ~68%)</Pill>
      <Pill active={spec === "frost"} onClick={() => setSpec("frost")}>Frost (ур. 6)</Pill>
    </Row>
  );
  if (spec === "fire") return <FireSims specPills={specPills} />;
  if (spec === "arcane") return <ArcaneSims specPills={specPills} />;
  return <MageLegacy spec={spec} specPills={specPills} />;
}
